    <div className={className || `h-[61.988px] relative rounded-[var(--fd-radius-lg,12px)] ${isDefaultAndDefaultAndIsTtsOrSettings ? "w-[77.96px]" : "w-[77.951px]"}`} id={isSettingsAndDefaultAndDefault ? "node-1023_17689" : isAppearanceAndDefaultAndDefault ? "node-1023_17685" : isTtsAndDefaultAndDefault ? "node-1023_17681" : "node-1023_17677"}>
