        {module === "Directory" && state === "Default" && interaction === "Default" && (
          <div className="absolute left-[9px] size-[23.993px] top-[9px]" data-node-id="1023:17679" data-name="Icon/directory">
            <div className="absolute left-0 size-[23.993px] top-0" data-node-id="I1023:17679;408:71" data-name="Tabler/list/outline">
              <img alt="" className="absolute block inset-0 max-w-none size-full" src={imgTablerListOutline} />
            </div>
