        )}
        {isTtsAndDefaultAndDefault && (
          <div className="absolute left-[9px] size-[23.993px] top-[9px]" data-node-id="1023:17683" data-name="Icon/tts">
            <div className="absolute left-0 size-[23.993px] top-0" data-node-id="I1023:17683;408:79" data-name="Tabler/headphones/outline">
              <img alt="" className="absolute block inset-0 max-w-none size-full" src={imgTablerHeadphonesOutline} />
            </div>
          </div>
        )}
        {isAppearanceAndDefaultAndDefault && (
          <div className="absolute left-[9px] size-[23.993px] top-[9px]" data-node-id="1023:17687" data-name="Icon/appearance">
            <div className="absolute left-0 size-[23.993px] top-0" data-node-id="I1023:17687;408:84" data-name="Tabler/palette/outline">
              <img alt="" className="absolute block inset-0 max-w-none size-full" src={imgTablerPaletteOutline} />
