      <div className="absolute bg-size-[100px_100px,auto_auto,auto_auto,auto_auto] bg-top-left inset-[0.56px] overflow-clip" data-node-id="1023:18356" style={{ backgroundImage: `url("${imgPaperLayer}"), linear-gradient(180deg, rgb(251, 244, 233) 0%, rgb(239, 226, 208) 100%), url("data:image/svg+xml;utf8,<svg viewBox='0 0 388.89 842.88' xmlns='http://www.w3.org/2000/svg' preserveAspectRatio='none'><rect x='0' y='0' height='100%' width='100%' fill='url(%23grad)' opacity='1'/><defs><radialGradient id='grad' gradientUnits='userSpaceOnUse' cx='0' cy='0' r='10' gradientTransform='matrix(0 -71.799 -71.799 0 194.44 151.72)'><stop stop-color='rgba(255,255,255,0.7)' offset='0'/><stop stop-color='rgba(191,191,191,0.525)' offset='0.105'/><stop stop-color='rgba(128,128,128,0.35)' offset='0.21'/><stop stop-color='rgba(64,64,64,0.175)' offset='0.315'/><stop stop-color='rgba(0,0,0,0)' offset='0.42'/></radialGradient></defs></svg>"), url("data:image/svg+xml;utf8,<svg viewBox='0 0 388.89 842.88' xmlns='http://www.w3.org/2000/svg' preserveAspectRatio='none'><rect x='0' y='0' height='100%' width='100%' fill='url(%23grad)' opacity='1'/><defs><radialGradient id='grad' gradientUnits='userSpaceOnUse' cx='0' cy='0' r='10' gradientTransform='matrix(0 -59.601 -27.499 0 194.44 421.44)'><stop stop-color='rgba(0,0,0,0)' offset='0.56'/><stop stop-color='rgba(89,70,50,0.1)' offset='1'/></radialGradient></defs></svg>")` }} data-name="PaperLayer">
